    public Settings geometry_operations(Settings operations){var result=new Settings();var protectedRegions=new GArray();foreach(var item in operations.Values){var operation=item.AsGodotDictionary();if(Get(operation,"enabled",true).AsBool()&&Get(operation,"type",0).AsInt32()==13)protectedRegions.Add(new Settings{["position"]=Get(operation,"position",Vector3.Zero),["radius"]=Get(operation,"radius",.5)});}foreach(var entry in operations){var operation=entry.Value.AsGodotDictionary();if(Get(operation,"type",0).AsInt32() is 12 or 13 or 14)continue;var copy=new Settings();foreach(string key in GeometryFields)if(operation.TryGetValue(key,out var value))copy[key]=value;if(protectedRegions.Count>0)copy["protected_regions"]=protectedRegions.Duplicate(true);result[entry.Key]=copy;}return result;}
    public double resistance(Settings operations,Vector3 point){double multiplier=1;foreach(var item in operations.Values){var operation=item.AsGodotDictionary();int type=Get(operation,"type",0).AsInt32();if(!Get(operation,"enabled",true).AsBool()||type is not (12 or 13))continue;double distance=point.DistanceTo(Get(operation,"position",Vector3.Zero).AsVector3()),radius=Math.Max(.001,Get(operation,"radius",.5).AsDouble());if(distance>=radius)continue;if(type==13)return double.PositiveInfinity;multiplier*=Mathf.Lerp(1,Math.Max(.01,Get(operation,"amount",.25).AsDouble()),Math.Pow(1-distance/radius,Math.Max(.1,Get(operation,"falloff",2).AsDouble())));}return Math.Max(.01,multiplier);}
